-- demoRobot dev seed: RobotModel + 3 model-specific Flows + 1 generic
-- fallback Flow + 2 sample Assets, for the DemoRobotica workspace.
--
-- Fixture/test data only — NOT a real-customer-data import mechanism
-- (analisi.md §12.1). compiledPrompt/retrievalDocument/hash below were
-- generated by the real compileFlow() (apps/backend/src/application/demorobot/
-- flow-compiler.service.ts), not hand-written, so they match the actual
-- compiler contract byte-for-byte.
--
-- Guarded on the workspace slug so it only runs against the intended
-- DemoRobotica workspace and is idempotent (ON CONFLICT DO NOTHING).

DO $$
DECLARE
  v_workspace_id TEXT;
BEGIN
  SELECT id INTO v_workspace_id FROM "Workspace" WHERE slug = 'demorobotica' LIMIT 1;

  IF v_workspace_id IS NULL THEN
    RAISE NOTICE 'DemoRobotica workspace not found (slug=demorobotica) — skipping demoRobot seed.';
    RETURN;
  END IF;

  -- Align workspace configuration with the demoRobot custom chatbot module
  -- (analisi.md §2, §12.1) — was created from a generic e-commerce template.
  UPDATE "Workspace"
  SET "customChatbotId" = 'demorobot',
      "businessType" = 'other',
      "welcomeMessage" = 'Welcome! I''m your DemoRobot technical support assistant. I can help you diagnose problems with your robot. How can I help you today?',
      "hasProductCatalog" = false,
      "hasCart" = false,
      "hasOrderTracking" = false
  WHERE id = v_workspace_id;

  -- RobotModel
  INSERT INTO "robot_models" (id, "workspaceId", name, slug, manufacturer, description, "lookupRules", "createdAt", "updatedAt")
  VALUES ('cm_seed_demorobot_x200', v_workspace_id, 'RoboCut X200', 'robocut-x200', 'DemoRobotica', 'Robot da giardinaggio/taglio erba, modello di test per lo sviluppo.', '{"prefix": "RCX200"}'::jsonb, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO "demorobot_flows" (id, "workspaceId", "robotModelId", title, description, keywords, "retrievalDocument", embedding, "compiledPrompt", hash, "createdAt", "updatedAt")
  VALUES ('cm_seed_flow_rumore', v_workspace_id, 'cm_seed_demorobot_x200', 'Rumore strano', 'Diagnostica per rumori anomali durante il funzionamento — copre il pattern a check sequenziali fino a escalation finale.', ARRAY['vibra', 'cigola', 'ronzio']::TEXT[], 'Rumore strano
vibra, cigola, ronzio
Il robot è acceso?
Il wifi è connesso?
Il cut scheduling è attivo?
Tutti i check sono OK ma il rumore persiste. Serve un tecnico.', ARRAY[]::DOUBLE PRECISION[], '## FLOW: Rumore strano

### Q: Il robot è acceso?
- If "Sì" → continue to: "Il wifi è connesso?"

### Q: Il wifi è connesso?
(collect as: wifiConnected, type: boolean)
- If "Sì" → continue to: "Il cut scheduling è attivo?"

### Q: Il cut scheduling è attivo?
(collect as: cutSchedulingActive, type: boolean)
- If "Sì" → continue to: "Tutti i check sono OK ma il rumore persiste. Serve un tecnico."

### Q: Tutti i check sono OK ma il rumore persiste. Serve un tecnico.
(terminal: ESCALATE, allowed tools: remember, escalate_to_operator)
', 'f8dacc4f04aecd709eed7b477b91ea565beaf3185d1a1d5c9151c58fef006b7b', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO "demorobot_flows" (id, "workspaceId", "robotModelId", title, description, keywords, "retrievalDocument", embedding, "compiledPrompt", hash, "createdAt", "updatedAt")
  VALUES ('cm_seed_flow_wifi', v_workspace_id, 'cm_seed_demorobot_x200', 'Wifi non si connette', 'Diagnostica connettività wifi — copre il pattern puramente self-service.', ARRAY['wifi', 'rete', 'connessione']::TEXT[], 'Wifi non si connette
wifi, rete, connessione
Il led wifi lampeggia?
Prova a riavviare il router e il robot. Il problema è risolto?', ARRAY[]::DOUBLE PRECISION[], '## FLOW: Wifi non si connette

### Q: Il led wifi lampeggia?
(collect as: wifiLedBlinking, type: boolean)
- If "Sì" → continue to: "Prova a riavviare il router e il robot. Il problema è risolto?"

### Q: Prova a riavviare il router e il robot. Il problema è risolto?
(terminal: SELF_SERVICE, allowed tools: remember)
', '5ef21cd8e14b79aa7a29132b4b7b90960c93e72c5bb980d51c2ea9d4aba9fa34', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO "demorobot_flows" (id, "workspaceId", "robotModelId", title, description, keywords, "retrievalDocument", embedding, "compiledPrompt", hash, "createdAt", "updatedAt")
  VALUES ('cm_seed_flow_fumo', v_workspace_id, 'cm_seed_demorobot_x200', 'Il robot fa fumo', 'Caso di emergenza tecnica — copre il pattern di escalation immediata su una singola risposta a metà percorso.', ARRAY['fumo', 'bruciato', 'odore']::TEXT[], 'Il robot fa fumo
fumo, bruciato, odore
Il robot sta ancora fumando in questo momento?
Verifica visivamente eventuali danni esterni. Il problema è risolto?', ARRAY[]::DOUBLE PRECISION[], '## FLOW: Il robot fa fumo

