  ON CONFLICT (id) DO NOTHING;

  INSERT INTO "demorobot_flows" (id, "workspaceId", "robotModelId", title, description, keywords, "retrievalDocument", embedding, "compiledPrompt", hash, "createdAt", "updatedAt")
  VALUES ('cm_seed_flow_generic', v_workspace_id, NULL, 'Diagnostica generica', 'Flow di fallback del workspace, usato quando il retrieval non trova un match specifico per il modello.', ARRAY[]::TEXT[], 'Diagnostica generica
Il robot è acceso?
Il wifi è connesso?
Il cut scheduling è attivo?
Tutti i check base sono OK. Serve un tecnico per una diagnosi più approfondita.', ARRAY[]::DOUBLE PRECISION[], '## FLOW: Diagnostica generica

### Q: Il robot è acceso?
- If "Sì" → continue to: "Il wifi è connesso?"

### Q: Il wifi è connesso?
(collect as: wifiConnected, type: boolean)
- If "Sì" → continue to: "Il cut scheduling è attivo?"

