(terminal: ESCALATE, allowed tools: remember, escalate_to_operator)
', '0716f3e497b474f0cc7c748adaed098758ca174f407ad0c68ce3fd37c662cabd', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
  ON CONFLICT (id) DO NOTHING;

  -- FlowNode + FlowEdge for flow1 (Rumore strano)
  INSERT INTO "demorobot_flow_nodes" (id, "flowId", question, "positionX", "positionY", "fieldKey", "fieldType", "terminalType", "createdAt", "updatedAt") VALUES
    ('rs_n1', 'cm_seed_flow_rumore', 'Il robot è acceso?', 0, 0, NULL, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('rs_n2', 'cm_seed_flow_rumore', 'Il wifi è connesso?', 280, 0, 'wifiConnected', 'boolean', NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('rs_n3', 'cm_seed_flow_rumore', 'Il cut scheduling è attivo?', 560, 0, 'cutSchedulingActive', 'boolean', NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('rs_n4', 'cm_seed_flow_rumore', 'Tutti i check sono OK ma il rumore persiste. Serve un tecnico.', 840, 0, NULL, NULL, 'ESCALATE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO "demorobot_flow_edges" (id, "sourceNodeId", "targetNodeId", label, "triggersEscalation", "createdAt") VALUES
    ('rs_e1', 'rs_n1', 'rs_n2', 'Sì', false, CURRENT_TIMESTAMP),
    ('rs_e2', 'rs_n2', 'rs_n3', 'Sì', false, CURRENT_TIMESTAMP),
    ('rs_e3', 'rs_n3', 'rs_n4', 'Sì', false, CURRENT_TIMESTAMP)
  ON CONFLICT (id) DO NOTHING;

  -- FlowNode + FlowEdge for flow2 (Wifi non si connette)
  INSERT INTO "demorobot_flow_nodes" (id, "flowId", question, "positionX", "positionY", "fieldKey", "fieldType", "terminalType", "createdAt", "updatedAt") VALUES
    ('wf_n1', 'cm_seed_flow_wifi', 'Il led wifi lampeggia?', 0, 0, 'wifiLedBlinking', 'boolean', NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('wf_n2', 'cm_seed_flow_wifi', 'Prova a riavviare il router e il robot. Il problema è risolto?', 280, 0, NULL, NULL, 'SELF_SERVICE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO "demorobot_flow_edges" (id, "sourceNodeId", "targetNodeId", label, "triggersEscalation", "createdAt") VALUES
    ('wf_e1', 'wf_n1', 'wf_n2', 'Sì', false, CURRENT_TIMESTAMP)
  ON CONFLICT (id) DO NOTHING;

  -- FlowNode + FlowEdge for flow3 (Il robot fa fumo) — immediate escalation on one answer
  INSERT INTO "demorobot_flow_nodes" (id, "flowId", question, "positionX", "positionY", "fieldKey", "fieldType", "terminalType", "createdAt", "updatedAt") VALUES
    ('sm_n1', 'cm_seed_flow_fumo', 'Il robot sta ancora fumando in questo momento?', 0, 0, NULL, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('sm_n2', 'cm_seed_flow_fumo', 'Verifica visivamente eventuali danni esterni. Il problema è risolto?', 280, 120, NULL, NULL, 'SELF_SERVICE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO "demorobot_flow_edges" (id, "sourceNodeId", "targetNodeId", label, "triggersEscalation", "createdAt") VALUES
    ('sm_e1', 'sm_n1', NULL, 'Sì', true, CURRENT_TIMESTAMP),
    ('sm_e2', 'sm_n1', 'sm_n2', 'No', false, CURRENT_TIMESTAMP)
  ON CONFLICT (id) DO NOTHING;

  -- FlowNode + FlowEdge for the generic fallback flow
  INSERT INTO "demorobot_flow_nodes" (id, "flowId", question, "positionX", "positionY", "fieldKey", "fieldType", "terminalType", "createdAt", "updatedAt") VALUES
    ('gn_n1', 'cm_seed_flow_generic', 'Il robot è acceso?', 0, 0, NULL, NULL, NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('gn_n2', 'cm_seed_flow_generic', 'Il wifi è connesso?', 280, 0, 'wifiConnected', 'boolean', NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('gn_n3', 'cm_seed_flow_generic', 'Il cut scheduling è attivo?', 560, 0, 'cutSchedulingActive', 'boolean', NULL, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('gn_n4', 'cm_seed_flow_generic', 'Tutti i check base sono OK. Serve un tecnico per una diagnosi più approfondita.', 840, 0, NULL, NULL, 'ESCALATE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
  ON CONFLICT (id) DO NOTHING;

  INSERT INTO "demorobot_flow_edges" (id, "sourceNodeId", "targetNodeId", label, "triggersEscalation", "createdAt") VALUES
    ('gn_e1', 'gn_n1', 'gn_n2', 'Sì', false, CURRENT_TIMESTAMP),
    ('gn_e2', 'gn_n2', 'gn_n3', 'Sì', false, CURRENT_TIMESTAMP),
    ('gn_e3', 'gn_n3', 'gn_n4', 'Sì', false, CURRENT_TIMESTAMP)
  ON CONFLICT (id) DO NOTHING;

  -- Sample assets (analisi.md §12.1: 1 PDF finto + 1 immagine, per verificare
