  -- are dev fixtures, not real uploaded files.
  INSERT INTO "demorobot_assets" (id, "robotModelId", type, url, title, summary, language, "createdAt", "updatedAt") VALUES
    ('cm_seed_asset_manual', 'cm_seed_demorobot_x200', 'document', 'https://example.com/demorobot/manuale-x200.pdf', 'Manuale RoboCut X200', 'Manuale utente completo del robot, incluse istruzioni per il reset wifi.', 'it', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
    ('cm_seed_asset_photo', 'cm_seed_demorobot_x200', 'image', 'https://example.com/demorobot/led-wifi-x200.jpg', 'Foto del led wifi', 'Foto di riferimento per individuare il led wifi sul robot.', 'it', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
  ON CONFLICT (id) DO NOTHING;

END $$;
